def _create_sqlite_rules():
    op.execute("""
        CREATE TRIGGER trg_parametros_vigencia_insert
        BEFORE INSERT ON parametros_nomina
        WHEN EXISTS (
            SELECT 1 FROM parametros_nomina p
            WHERE p.empresa_id IS NEW.empresa_id AND p.codigo = NEW.codigo
              AND p.vigente_desde <= COALESCE(NEW.vigente_hasta, '9999-12-31')
              AND COALESCE(p.vigente_hasta, '9999-12-31') >= NEW.vigente_desde
        )
        BEGIN
            SELECT RAISE(ABORT, 'Las vigencias se solapan para el mismo codigo y empresa');
        END
    """)
    op.execute("""
        CREATE TRIGGER trg_parametros_vigencia_update
        BEFORE UPDATE ON parametros_nomina
        WHEN EXISTS (
            SELECT 1 FROM parametros_nomina p
            WHERE p.id <> OLD.id AND p.empresa_id IS NEW.empresa_id
              AND p.codigo = NEW.codigo
              AND p.vigente_desde <= COALESCE(NEW.vigente_hasta, '9999-12-31')
              AND COALESCE(p.vigente_hasta, '9999-12-31') >= NEW.vigente_desde
        )
        BEGIN
            SELECT RAISE(ABORT, 'Las vigencias se solapan para el mismo codigo y empresa');
        END
    """)
    op.execute("""
        CREATE TRIGGER trg_tarifas_vigencia_insert
        BEFORE INSERT ON tarifas_recargo
        WHEN EXISTS (
            SELECT 1 FROM tarifas_recargo t
            WHERE t.empresa_id IS NEW.empresa_id
              AND t.tipo_codigo = NEW.tipo_codigo
              AND t.vigente_desde <= COALESCE(NEW.vigente_hasta, '9999-12-31')
              AND COALESCE(t.vigente_hasta, '9999-12-31') >= NEW.vigente_desde
        )
        BEGIN
            SELECT RAISE(ABORT, 'Las vigencias se solapan para el mismo codigo y empresa');
        END
    """)
    op.execute("""
        CREATE TRIGGER trg_tarifas_vigencia_update
        BEFORE UPDATE ON tarifas_recargo
        WHEN EXISTS (
            SELECT 1 FROM tarifas_recargo t
            WHERE t.id <> OLD.id AND t.empresa_id IS NEW.empresa_id
              AND t.tipo_codigo = NEW.tipo_codigo
              AND t.vigente_desde <= COALESCE(NEW.vigente_hasta, '9999-12-31')
              AND COALESCE(t.vigente_hasta, '9999-12-31') >= NEW.vigente_desde
        )
        BEGIN
            SELECT RAISE(ABORT, 'Las vigencias se solapan para el mismo codigo y empresa');
        END
    """)

    id_conditions = {
        "INSERT": "id = NEW.nomina_id",
        "UPDATE": "id IN (OLD.nomina_id, NEW.nomina_id)",
        "DELETE": "id = OLD.nomina_id",
    }
    for action, id_condition in id_conditions.items():
        op.execute(f"""
            CREATE TRIGGER trg_detalle_totales_{action.lower()}
            AFTER {action} ON detalles_nomina
            BEGIN
                UPDATE nominas SET
                    total_devengado = COALESCE((
                        SELECT SUM(d.valor)
                        FROM detalles_nomina d
                        JOIN conceptos_nomina c ON c.id = d.concepto_id
                        WHERE d.nomina_id = nominas.id AND c.tipo = 'DEVENGADO'
                    ), 0),
                    total_deducciones = COALESCE((
                        SELECT SUM(d.valor)
                        FROM detalles_nomina d
                        JOIN conceptos_nomina c ON c.id = d.concepto_id
                        WHERE d.nomina_id = nominas.id AND c.tipo = 'DEDUCCION'
                    ), 0)
                WHERE {id_condition};
            END
        """)

    op.execute("""
        CREATE TRIGGER trg_bloquear_detalle_insert
        BEFORE INSERT ON detalles_nomina
        WHEN (SELECT estado FROM nominas WHERE id = NEW.nomina_id) <> 'BORRADOR'
        BEGIN
            SELECT RAISE(ABORT, 'No se puede modificar el detalle de una nomina cerrada');
        END
    """)
    op.execute("""
        CREATE TRIGGER trg_bloquear_detalle_update
        BEFORE UPDATE ON detalles_nomina
        WHEN (SELECT estado FROM nominas WHERE id = OLD.nomina_id) <> 'BORRADOR'
          OR (SELECT estado FROM nominas WHERE id = NEW.nomina_id) <> 'BORRADOR'
        BEGIN
            SELECT RAISE(ABORT, 'No se puede modificar el detalle de una nomina cerrada');
        END
    """)
    op.execute("""
        CREATE TRIGGER trg_bloquear_detalle_delete
        BEFORE DELETE ON detalles_nomina
        WHEN (SELECT estado FROM nominas WHERE id = OLD.nomina_id) <> 'BORRADOR'
        BEGIN
            SELECT RAISE(ABORT, 'No se puede modificar el detalle de una nomina cerrada');
        END
    """)
    op.execute("""
        CREATE VIEW vw_saldo_vacaciones AS
        SELECT c.id AS contrato_id, c.empleado_id,
               COALESCE(SUM(m.dias), 0) AS dias_saldo
        FROM contratos c
        LEFT JOIN movimientos_vacaciones m ON m.contrato_id = c.id
        GROUP BY c.id, c.empleado_id
    """)
    op.execute("""
        CREATE VIEW vw_resumen_nomina AS
        SELECT n.id AS nomina_id, e.empresa_id, e.numero_documento, e.nombres, e.apellidos,
               p.fecha_inicio, p.fecha_fin, n.total_devengado, n.total_deducciones,
               n.neto_pagar, n.estado
        FROM nominas n
        JOIN contratos c ON c.id = n.contrato_id
        JOIN empleados e ON e.id = c.empleado_id
        JOIN periodos_nomina p ON p.id = n.periodo_id
    """)


